<?php
namespace App\Http\Controllers; use App\Models\Schedule; use App\Models\Movie; use App\Models\TicketPrice; use Illuminate\Http\Request;
class ScheduleController extends Controller {public function index(){$schedules=Schedule::with(['movie','ticketPrice'])->latest()->paginate(10);return view('admin.schedules.index',compact('schedules'));} public function create(){$movies=Movie::all();$prices=TicketPrice::all();$schedule=new Schedule;return view('admin.schedules.form',compact('movies','prices','schedule'));} public function store(Request $r){$d=$r->validate(['movie_id'=>'required|exists:movies,id','ticket_price_id'=>'required|exists:ticket_prices,id','show_time'=>'required|date','studio'=>'required|string|max:100']);Schedule::create($d);return redirect()->route('schedules.index')->with('success','Jadwal ditambahkan.');} public function show(Schedule $schedule){return redirect()->route('schedules.index');} public function edit(Schedule $schedule){$movies=Movie::all();$prices=TicketPrice::all();return view('admin.schedules.form',compact('movies','prices','schedule'));} public function update(Request $r,Schedule $schedule){$d=$r->validate(['movie_id'=>'required|exists:movies,id','ticket_price_id'=>'required|exists:ticket_prices,id','show_time'=>'required|date','studio'=>'required|string|max:100']);$schedule->update($d);return redirect()->route('schedules.index')->with('success','Jadwal diperbarui.');} public function destroy(Schedule $schedule){$schedule->delete();return redirect()->route('schedules.index')->with('success','Jadwal dihapus.');}}
